export type IconTone = 'neutral' | 'accent';
interface BoxProps {
    id?: string;
    size?: number;
}
/** Props of every icon: the box props, plus `tone` and `size`. */
export type IconProps = Omit<BoxProps, 'size'> & {
    /**
     * Glyph colour family.
     * @default 'neutral'
     */
    tone?: IconTone;
    /**
     * Width and height in pixels.
     * @default 24
     */
    size?: number;
};
